#!/usr/bin/env python3
"""Bind the three visual-release packages to final build inputs and real QA evidence."""
from pathlib import Path
import hashlib,json,re,statistics
R=Path(__file__).resolve().parents[1];version='1.9.7.7'
def sha(p):
 with p.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
shared=['v1977-preservation.json','v1977-ui-test.json','v1977-pixels.json']
for name in shared:assert json.loads((R/'logs'/name).read_text())['exit']==0,name
ui=json.loads((R/'logs/v1977-ui-test.json').read_text())
for rel,digest in ui['source_sha256'].items():assert sha(R/rel)==digest,rel
assert ui['fixture_sha256']==sha(R/'qa/v1977_render.c')
bench=[]
for size in [640,1024]:
 rows=[float(ms) for w,ms in re.findall(r'RENDER_BUDGET \d+ (\d+) ([\d.]+)',(R/'logs/v1977-ui-test.log').read_text()) if int(w)==size]
 assert len(rows)==50
 bench.append({'width':size,'samples':len(rows),'median_host_ASan_ms':statistics.median(rows),'max_host_ASan_ms':max(rows)})
(R/'logs/v1977-render-cost.json').write_text(json.dumps({'version':version,'exit':0,'warm_icon_surfaces_created_in_100_frames':0,'warm_auralis_surfaces_created_in_30_frames_each_state_each_resolution':0,'icon_cache_bytes_limit':2097152,'panel_cache_bytes_limit':4194304,'text_cache_existing_bytes_limit':6291456,'opaque_panels_fill_interior_blend_only_corners':True,'whole_app_supersampling':False,'CPU_scheduler_and_frame_policy_unchanged':True,'informational_host_timings':bench,'timing_note':'Software renderer with ASan/UBSan on host; not a device FPS, power or temperature measurement.','physical_tested':False},indent=2)+'\n')
shared+=['v1977-render-cost.json']
for rom,label,folder in [('stock','Stock','stock'),('nextui','NextUI','upstream'),('nxredux','NXRedux','nxredux')]:
 binary=R/f'{folder}/bin/tg5040/musicplayer.elf';installer=R/f'dist/{rom}-release/NXT_Retro_Music_v{version}_{label}.zip';ota=installer.with_name(f'NXT_OTA_Google_Drive_v{version}_{label}.zip')
 names=shared+[f'v1977-{kind}-{rom}.json' for kind in ['loader','package-qa','ota-qa','ota-publisher-kit']]
 for name in names:
  d=json.loads((R/'logs'/name).read_text());assert d['exit']==0,name
  if name.startswith('v1977-loader-'):assert d['binary_sha256']==sha(binary)
  if name.startswith('v1977-package-qa-'):assert d['installer_sha256']==sha(installer) and d['kit_sha256']==sha(ota)
  if name.startswith('v1977-ota-qa-'):assert d['installer_sha256']==sha(installer) and d['baseline_installed_version_fixture']=='1.9.7.6'
 inputs=R/f'{folder}/BUILD_INPUTS_v{version}.json';build=json.loads(inputs.read_text());assert build['binary_sha256']==sha(binary)
 for rel,digest in build['sources'].items():assert sha(R/rel)==digest,rel
 report={'version':version,'rom':rom,'baseline':'unified v1.9.7.6','build':{'exit':0,'compiler':'GCC 8.3.0 AArch64','optimization':'O2','ROM_define':'NXT_ROM_'+rom.upper(),'freshly_recompiled':True,'source_fingerprints_verified':True,'inputs_file_sha256':sha(inputs),'build_log_sha256':sha(R/'logs/v1977-release-build.log')},'binary_sha256':sha(binary),'installer':installer.name,'installer_size':installer.stat().st_size,'installer_sha256':sha(installer),'OTA_kit':ota.name,'OTA_kit_size':ota.stat().st_size,'OTA_kit_sha256':sha(ota),'checks':{name:{'sha256':sha(R/'logs'/name)} for name in names},'changes':['316 vector icons at 192 px, alpha-correct area downsampling cached at native size','AA rounded edges/circles/diagonals; opaque interiors keep fast fills','Larger symmetric Auralis controls, bright filled active state with dark glyphs','Filtered cover/chassis/avatar/vinyl label scaling and rectangular cover bounds','Ocean Blue and Boombox title/art bounds; bilingual footer kept clear'],'preserved':'Audio, DSP/DSD, online backends, controls, scheduler/performance/CPU/LED, translations, library, profiles, compositor and OTA code verified unchanged against source baseline.','native_renderer_sizes':[1024,640],'native_test_frames':ui['native_png_frames'],'fonts_total':60,'themes_total':51,'official_OTA_feed':json.loads((R/'SOURCE.json').read_text())['official_OTA_sources'][rom],'online_backends_rebuilt':False,'physical_ROM_DAC_Bluetooth_tested':False,'actual_device_FPS_measured':False,'thermal_battery_measured':False,'live_OTA_feed_uploaded':False}
 (R/f'BUILD_REPORT_v{version}_{label}.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
p=R/'SOURCE.json';m=json.loads(p.read_text());m.update(release_ready=True,stock_status='Three fresh ARM64 builds, ASan/UBSan native UI at two sizes, active-state/alignment pixels, preservation, QEMU loaders, full packages and production OTA installer fixtures passed. No physical device or live OTA publication.',unified_source_status='Final v1.9.7.7 three-ROM fingerprints and current evidence verified',v1977_verification='RELEASE_QA_v1.9.7.7.md');p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
lines=['# Release QA — v1.9.7.7','','Baseline: unified v1.9.7.6. Version corrected by the user to **1.9.7.7**.','','## Passed software checks','','- Fresh O2 GCC 8.3.0 ARM64 frontends for Stock, NextUI and NX Redux; every C/H/INC build fingerprint matches the final tree. QEMU runs `--build-info` and `--help` for all three real binaries.','- Native production SDL/TTF renderer with ASan/UBSan: 51 themes, 60 multilingual fonts, 1024×768 and 640×480; '+str(ui['native_png_frames'])+' PNG frames. Original artwork aspect-fit, bilingual/italic lyrics, word highlights, preview Apply/Cancel, settings/controls/album preview flows remain exercised.','- Checkerboard downscaling averages detail, alpha edges retain white without dark fringes, rounded corners contain fractional coverage, diagonal drawing respects clipping. Cold/warm cached art matches filtered references.','- Repeated icon draws at two sizes create zero new surfaces in 100 warmed iterations. Auralis creates zero new surfaces in 30 warmed paints per state per resolution; status clock is fixed in this deterministic fixture.','- 200 native menu/player theme images checked; both-size active repeat/shuffle states increase mean brightness by over 120 levels in the circular control. Changed pixels stay within the affected controls. Previous/next mirrored mask mean error <0.01 RGB level in a flat-cover fixture; pixel rounding tolerance 1 px.','- Review found and fixed cramped Ocean Blue metadata/cover placement, widened Boombox metadata and kept song information above the bilingual reserved footer. Album fitting honours both width and height.','- 894 C/H/INC baseline files compared: only 10 intended UI/version files changed. 414 non-icon resource files and all online runtime executables remain byte-identical. 316 existing icons regenerated from pinned Lucide/original SVGs; coloured brands and emoji unchanged.','- All three full installer ZIPs: CRC, exact executable/resource bytes, target paths, current config/state/pak versions, official ROM feed and permission bits; no private data. OTA kit contains the exact checked installer and current offline publisher tools.','- Production OTA worker/installer under ASan/UBSan upgrades an installed 1.9.7.6 fixture for each ROM: Drive confirmation, size/SHA, wrong-ROM/HTML rejection, cancellation/reaping, old app backup and preserved settings/profiles/library/translation keys/cache/wallpaper.','','## Performance boundaries','','No full-app supersampling, extra background service, CPU clock increase or scheduler change. Icon cache 2 MiB, rounded mask cache 4 MiB, existing text cache 6 MiB; art is prepared on source/size/style change. Opaque panel interiors use fast fills and blend only AA corners. Source artwork and the physical screen limit real detail; upscaling a low-resolution cover cannot create original HD detail.','','Host ASan timing is informational and is not a device performance guarantee:']
for b in bench:lines.append(f"- {b['width']} px / 50 warm legacy theme samples: median {b['median_host_ASan_ms']:.3f} ms, maximum {b['max_host_ASan_ms']:.3f} ms on this host.")
lines+=['','No physical TrimUI playback, scan-out, FPS, temperature or battery test was performed. No live OTA feed was uploaded. App functions involving audio/network/hardware in the visual harness use explicit fixtures. Current SoundCloud/Spotify backends are preserved binaries from v1.9.7.6; no new live-service playback claim.','','## Package hashes','']
for label in ['Stock','NextUI','NXRedux']:
 d=json.loads((R/f'BUILD_REPORT_v{version}_{label}.json').read_text());lines += [f"- {d['installer']}: `{d['installer_sha256']}`",f"- {d['OTA_kit']}: `{d['OTA_kit_sha256']}`"]
(R/f'RELEASE_QA_v{version}.md').write_text('\n'.join(lines)+'\n')
print('PASS final reports bound to three exact binaries/installers/OTA kits, source fingerprints and current evidence')
